const COST_RE = /^[0-9]+$/

/**
 * Parses the build graph from the raw input text.
 *
 * Returns { cost: Map<name, number>, deps: Map<name, string[]> } where deps
 * maps a task name to the sorted, deduplicated list of names it depends on.
 * Throws CliError on any malformed input, with exitCode 2.
 */
export function parseGraph(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop()
  }

  const cost = new Map()
  const depSets = new Map() // name -> Set of dependency names
  // Records every name used on a dep line, in input order, for the
  // "unknown task" check: [name, lineNumber] pairs in encounter order.
  const usedNames = []

  for (let i = 0; i < lines.length; i++) {
    const lineNumber = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const words = trimmed.split(/\s+/)
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) {
        throw new CliError(`error: line ${lineNumber}: expected task <name> <cost>`, 2)
      }
      const name = words[1]
      const costWord = words[2]
      if (!NAME_RE.test(name)) {
        throw new CliError(`error: line ${lineNumber}: invalid task name ${name}`, 2)
      }
      if (!COST_RE.test(costWord)) {
        throw new CliError(`error: line ${lineNumber}: cost must be a non-negative integer`, 2)
      }
      if (cost.has(name)) {
        throw new CliError(`error: line ${lineNumber}: task ${name} is declared twice`, 2)
      }
      cost.set(name, parseInt(costWord, 10))
      if (!depSets.has(name)) depSets.set(name, new Set())
    } else if (directive === 'dep') {
      if (words.length < 3) {
        throw new CliError(`error: line ${lineNumber}: expected dep <name> <dependency>...`, 2)
      }
      const name = words[1]
      const dependencies = words.slice(2)
      usedNames.push(name)
      for (const dep of dependencies) usedNames.push(dep)
      if (!depSets.has(name)) depSets.set(name, new Set())
      const set = depSets.get(name)
      for (const dep of dependencies) set.add(dep)
    } else {
      throw new CliError(`error: line ${lineNumber}: unknown directive ${directive}`, 2)
    }
  }

  for (const name of usedNames) {
    if (!cost.has(name)) {
      throw new CliError(`error: unknown task ${name}`, 2)
    }
  }

  const deps = new Map()
  for (const [name, set] of depSets) {
    deps.set(name, [...set].sort())
  }

  return { cost, deps }
}
"}

