/**
 * Finds the first cycle a depth-first search finds, starting from each task
 * in ascending name order and walking each task's dependencies in ascending
 * name order. Returns the cycle as an array of names, from the re-entered
 * task through the search stack, back to that task; or null if acyclic.
 */
export function findCycle(names, deps) {
  const color = new Map()
  for (const name of names) color.set(name, 0)
  const stack = []

  function dfs(node) {
    color.set(node, 1)
    stack.push(node)
    const dependencies = deps.get(node) || []
    for (const dep of dependencies) {
      const state = color.get(dep)
      if (state === 1) {
        const idx = stack.indexOf(dep)
        return stack.slice(idx).concat(dep)
      }
      if (state === 0) {
        const found = dfs(dep)
        if (found) return found
      }
    }
    color.set(node, 2)
    stack.pop()
    return null
  }

  for (const name of names) {
    if (color.get(name) === 0) {
      const found = dfs(name)
      if (found) return found
    }
  }
  return null
}

/** Throws CycleError if the graph has a cycle. */
export function checkAcyclic(names, deps) {
  const cycle = findCycle(names, deps)
  if (cycle) throw new CycleError(cycle)
}
"}

