/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */

import { CliError, CycleError } from './errors.js'
import { parseGraph } from './parse.js'
import { checkAcyclic } from './cycle.js'
import { computeSchedule, computeWaves } from './schedule.js'
import { packSchedule } from './pack.js'

function readStdin() {
  const chunks = []
  const fs = require('node:fs')
  try {
    const data = fs.readFileSync(0, 'utf8')
    return data
  } catch (err) {
    return ''
  }
}

function usageError() {
  throw new CliError('error: usage: cli.js waves|explain|pack <workers>', 2)
}

function parseArgs(argv) {
  if (argv.length === 1 && (argv[0] === 'waves' || argv[0] === 'explain')) {
    return { mode: argv[0] }
  }
  if (argv.length === 2 && argv[0] === 'pack') {
    const workerWord = argv[1]
    if (!/^[1-9][0-9]*$/.test(workerWord)) {
      throw new CliError('error: workers must be a positive integer', 2)
    }
    return { mode: 'pack', workers: parseInt(workerWord, 10) }
  }
  usageError()
}

function main() {
  const argv = process.argv.slice(2)
  const args = parseArgs(argv)

  const input = readStdinSync()
  const { cost, deps } = parseGraph(input)
  const names = [...cost.keys()].sort()

  checkAcyclic(names, deps)

  if (args.mode === 'waves') {
    const { depth, total } = computeSchedule(names, cost, deps)
    const waves = computeWaves(names, depth)
    let output = ''
    for (let i = 0; i < waves.length; i++) {
      output += `wave ${i}: ${waves[i].join(' ')}\n`
    }
    output += `total ${total}\n`
    process.stdout.write(output)
  } else if (args.mode === 'explain') {
    const { start, finish, depth, total } = computeSchedule(names, cost, deps)
    let output = ''
    for (const name of names) {
      output += `${name} start=${start.get(name)} finish=${finish.get(name)} depth=${depth.get(name)}\n`
    }
    output += `total ${total}\n`
    process.stdout.write(output)
  } else if (args.mode === 'pack') {
    const { workerRuns, makespan } = packSchedule(names, cost, deps, args.workers)
    let output = ''
    for (let w = 0; w < workerRuns.length; w++) {
      const parts = workerRuns[w].map((run) => ` ${run.name}@${run.start}-${run.finish}`)
      output += `worker ${w}:${parts.join('')}\n`
    }
    output += `makespan ${makespan}\n`
    process.stdout.write(output)
  }
}

function readStdinSync() {
  const fs = require('node:fs')
  try {
    return fs.readFileSync(0, 'utf8')
  } catch (err) {
    return ''
  }
}

try {
  main()
} catch (err) {
  if (err instanceof CycleError) {
    process.stderr.write(err.message + '\n')
    process.exit(3)
  } else if (err instanceof CliError) {
    process.stderr.write(err.message + '\n')
    process.exit(err.exitCode)
  } else {
    throw err
  }
}
